<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {Room,RoomEvent} from 'livekit-client'
import {request} from './client'
import ClassWelcome from '../ClassWelcome.vue'
const showWelcome=ref(true)
const props=defineProps({grant:Object}),emit=defineEmits(['leave']),media=ref(null),error=ref(''),connected=ref(false),mic=ref(false),camera=ref(false),sharing=ref(false),devices=ref([]),recording=ref(props.grant.recording_status)
const chatMessages=ref([]),chatText=ref(''),chatError=ref(''),chatBusy=ref(false)
let room,poll,chatPoll,closed=false,polling=false,chatPolling=false
async function loadChat(){if(chatPolling||closed||!connected.value||props.grant.preview)return;chatPolling=true;try{const r=await request('live_classes','chat',{name:props.grant.name},'GET');if(!closed){chatMessages.value=r.messages;chatError.value=''}}catch(e){if(!closed)chatError.value=e.message}finally{chatPolling=false}}
async function sendChat(){if(chatBusy.value||!chatText.value.trim())return;chatBusy.value=true;try{const r=await request('live_classes','chat',{name:props.grant.name,text:chatText.value.trim()});chatMessages.value=r.messages;chatText.value='';chatError.value=''}catch(e){chatError.value=e.message}finally{chatBusy.value=false}}
const participants=ref([]),connection=ref('Connecting')
function syncPeople(){participants.value=room?[room.localParticipant,...room.remoteParticipants.values()].map(p=>({id:p.identity,name:p.name||'Participant',host:p.identity===props.grant.host_identity,microphone:p.isMicrophoneEnabled})):[]}
async function reconnect(){await action(async()=>{await room?.disconnect();media.value?.replaceChildren();const fresh=await request('live_classes','join',{name:props.grant.name});await room.connect(fresh.url,fresh.token);connected.value=true;connection.value='Connected';syncPeople();await loadChat()})}
async function refreshState(){if(polling||closed)return;polling=true;try{const state=await request('live_classes','room_status',{name:props.grant.name});if(closed)return;recording.value=state.recording_status;if(state.status!=='Live'){await room?.disconnect();connection.value='Class ended'}}catch(e){recording.value='Status unavailable';error.value=e.message;await room?.disconnect()}finally{polling=false}}
function hidden(){if(document.hidden&&room){room.localParticipant.setMicrophoneEnabled(false).catch(()=>{});room.localParticipant.setCameraEnabled(false).catch(()=>{});mic.value=false;camera.value=false}}
async function action(fn){try{error.value='';await fn()}catch(e){error.value=e.message}}
async function toggle(kind){await action(async()=>{if(props.grant.preview){if(kind==='mic')mic.value=!mic.value;else if(kind==='camera')camera.value=!camera.value;else sharing.value=!sharing.value;return}if(kind==='mic'){await room.localParticipant.setMicrophoneEnabled(!mic.value);mic.value=!mic.value}else if(kind==='camera'){await room.localParticipant.setCameraEnabled(!camera.value);camera.value=!camera.value}else{await room.localParticipant.setScreenShareEnabled(!sharing.value);sharing.value=!sharing.value}syncPeople()})}
async function record(){await action(async()=>{const r=await request('live_classes','control',{name:props.grant.name,action:recording.value==='Recording'?'stop_recording':'record'});recording.value=r.recording_status})}
onMounted(()=>action(async()=>{if(props.grant.preview){connected.value=true;connection.value='Preview only';participants.value=[{id:'preview',name:'Fictional teacher',microphone:false}];return}document.addEventListener('visibilitychange',hidden);room=new Room({adaptiveStream:true,dynacast:true});room.on(RoomEvent.TrackSubscribed,track=>{media.value?.appendChild(track.attach());syncPeople()});room.on(RoomEvent.TrackUnsubscribed,track=>track.detach().forEach(e=>e.remove()));room.on(RoomEvent.LocalTrackPublished,p=>{if(p.track&&p.track.kind==='video'){const element=p.track.attach();element.muted=true;media.value?.appendChild(element)}syncPeople()});room.on(RoomEvent.LocalTrackUnpublished,p=>p.track?.detach().forEach(e=>e.remove()));room.on(RoomEvent.Disconnected,()=>{connected.value=false;connection.value='Disconnected'});room.on(RoomEvent.Reconnecting,()=>connection.value='Reconnecting');room.on(RoomEvent.Reconnected,()=>{connection.value='Connected';connected.value=true;syncPeople()});for(const e of [RoomEvent.ParticipantConnected,RoomEvent.ParticipantDisconnected,RoomEvent.TrackMuted,RoomEvent.TrackUnmuted])room.on(e,()=>{mic.value=room.localParticipant.isMicrophoneEnabled;camera.value=room.localParticipant.isCameraEnabled;sharing.value=room.localParticipant.isScreenShareEnabled;syncPeople()});await room.connect(props.grant.url,props.grant.token);if(closed){await room.disconnect();return}connected.value=true;connection.value='Connected';syncPeople();poll=setInterval(refreshState,10000);chatPoll=setInterval(loadChat,3000);await loadChat();devices.value=await Room.getLocalDevices('audioinput')}))
onBeforeUnmount(()=>{closed=true;clearInterval(poll);clearInterval(chatPoll);document.removeEventListener('visibilitychange',hidden);room?.disconnect()})
</script>
<template><section class="panel"><ClassWelcome v-if="showWelcome" title="Your live classroom" :joined="true" @close="showWelcome=false"/><h2>Live classroom</h2><p role="status">{{connection}} Â· Recording: {{recording}}</p><p v-if="grant.preview">PREVIEW ONLY â€” fictional classroom. No camera, microphone or provider connection is opened.</p><p v-if="error" role="alert">{{error}}</p><div class="live-layout"><div><div ref="media" class="live-media"><div v-if="grant.preview" class="preview-stage">Fictional teacher Â· Algebra workshop</div></div><p v-for="p in participants" :key="p.id">{{p.name}} Â· {{p.microphone?'Microphone on':'Microphone off'}}</p></div><aside class="class-chat"><h3>Class chat</h3><p class="chat-help">Everyone in this live lesson can read messages. Chat is temporary.</p><div class="chat-log" role="log" aria-live="polite" aria-label="Live class messages"><p v-if="!chatMessages.length">Say hello or ask your teacher a question.</p><article v-for="message in chatMessages" :key="message.id"><strong>{{message.author}} <span v-if="message.host" class="host-label">Host</span></strong><p>{{message.text}}</p></article></div><p v-if="chatError" role="alert">{{chatError}}</p><form @submit.prevent="sendChat"><label for="live-chat-message">Message everyone</label><textarea id="live-chat-message" v-model="chatText" maxlength="1000" rows="2" :disabled="!connected||grant.preview" placeholder="Write a message…"/><button class="button primary" :disabled="chatBusy||!connected||!chatText.trim()||grant.preview">{{chatBusy?'Sending…':'Send'}}</button></form></aside></div><p v-if="grant.can_publish" class="chat-help">Your camera and microphone start off. Turn them on when you’re ready to participate.</p><button v-if="!connected&&!grant.preview" class="button subtle" @click="reconnect">Reconnect with server authorization</button><div class="inline wrap"><button v-if="grant.can_publish" class="button subtle" :disabled="!connected" @click="toggle('mic')">{{mic?'Mute':'Enable microphone'}}</button><button v-if="grant.can_publish" class="button subtle" :disabled="!connected" @click="toggle('camera')">{{camera?'Camera off':'Camera on'}}</button><button v-if="grant.can_control" class="button subtle" :disabled="!connected" @click="toggle('share')">{{sharing?'Stop sharing':'Share screen'}}</button><label v-if="devices.length">Microphone<select @change="action(()=>room.switchActiveDevice('audioinput',$event.target.value))"><option v-for="d in devices" :value="d.deviceId">{{d.label}}</option></select></label><button v-if="grant.can_control" class="button primary" :disabled="!['None','Recording'].includes(recording)" @click="record">{{recording==='Recording'?'Stop recording':'Record lesson'}}</button><button class="button subtle" @click="emit('leave')">Leave classroom</button></div></section></template>
<style scoped>.live-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:20px}.class-chat{border:1px solid #e3ddef;border-radius:16px;padding:16px;min-width:0}.chat-help{font-size:13px;color:#71677f;line-height:1.5}.chat-log{height:280px;overflow:auto;display:flex;flex-direction:column;gap:12px}.chat-log article{background:#f5f2fc;border-radius:10px;padding:10px}.chat-log p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}.host-label{font-size:11px;background:#552c85;color:white;border-radius:8px;padding:3px 7px}.class-chat form{display:grid;gap:10px;margin-top:12px}.class-chat textarea{width:100%;box-sizing:border-box;border:1px solid #d9d0e7;border-radius:10px;padding:10px}@media(max-width:800px){.live-layout{grid-template-columns:1fr}.chat-log{height:180px}}.live-media{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px;overflow:hidden;background:#171724;border-radius:18px;min-height:220px;margin:16px 0}.live-media :deep(video){display:block;width:100%;height:100%;min-width:0;max-height:65vh;object-fit:contain}.live-media :deep(audio){display:none}.preview-stage{padding:60px;color:#fff}</style>
